import{_ as a,o as r,c as o,a2 as s}from"./chunks/framework.BXzK3EA4.js";const m=JSON.parse('{"title":"ADR 0001: shared bare mirror and disposable workspaces","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0001-shared-git-mirror.md","filePath":"adr/0001-shared-git-mirror.md","lastUpdated":1788529216000}'),i={name:"adr/0001-shared-git-mirror.md"};function t(n,e,d,l,c,p){return r(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="adr-0001-shared-bare-mirror-and-disposable-workspaces" tabindex="-1">ADR 0001: shared bare mirror and disposable workspaces <a class="header-anchor" href="#adr-0001-shared-bare-mirror-and-disposable-workspaces" aria-label="Permalink to &quot;ADR 0001: shared bare mirror and disposable workspaces&quot;">​</a></h1><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>Use one persistent bare Git mirror per repository and derive isolated scanner workspaces from it. Aegis, not scanner plugins, owns network acquisition.</p><h2 id="rationale" tabindex="-1">Rationale <a class="header-anchor" href="#rationale" aria-label="Permalink to &quot;Rationale&quot;">​</a></h2><p>This prevents duplicate network clones, protects the canonical cache from scanner mutation, and gives incremental scanners a stable commit history. The cache adapter serializes repository operations and cleans temporary workspaces after execution.</p><h2 id="follow-up" tabindex="-1">Follow-up <a class="header-anchor" href="#follow-up" aria-label="Permalink to &quot;Follow-up&quot;">​</a></h2><p>Cluster-wide cache leases are required before scaling the operator/API beyond the chart&#39;s single-replica default.</p>',7)])])}const u=a(i,[["render",t]]);export{m as __pageData,u as default};
